/* ===== UniReg — colorful responsive styles ===== */
:root {
  --purple: #6c5ce7;
  --pink: #e84393;
  --orange: #fd9644;
  --yellow: #fdcb6e;
  --teal: #00b894;
  --blue: #0984e3;
  --red: #e74c3c;
  --ink: #2d3047;
  --muted: #6b6f86;
  --bg: #f6f4ff;
  --card: #ffffff;
  --border: #e6e2fb;
  --radius: 16px;
  --shadow: 0 8px 24px rgba(76, 61, 170, 0.12);
  --shadow-lg: 0 18px 40px rgba(76, 61, 170, 0.22);
  --grad-main: linear-gradient(135deg, #6c5ce7 0%, #e84393 55%, #fd9644 100%);
}

*, *::before, *::after { box-sizing: border-box; }
[hidden] { display: none !important; }

html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: "Segoe UI", system-ui, -apple-system, Roboto, "Helvetica Neue", Arial, sans-serif;
  color: var(--ink);
  background:
    radial-gradient(circle at 10% 0%, rgba(253, 203, 110, 0.25), transparent 40%),
    radial-gradient(circle at 90% 20%, rgba(0, 184, 148, 0.15), transparent 40%),
    var(--bg);
  line-height: 1.55;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}
body.modal-open { overflow: hidden; }
main { flex: 1; }
img { max-width: 100%; }
a { color: var(--purple); }
h1, h2, h3 { line-height: 1.2; margin: 0 0 .5rem; }

.container { width: min(1200px, 100% - 2.5rem); margin-inline: auto; }
.section { padding: 2.5rem 0; }
.section-title { font-size: 1.6rem; margin-bottom: 1.25rem; }
.section-title.small { font-size: 1.25rem; margin: 0; }
.section-head { display: flex; justify-content: space-between; align-items: center; gap: 1rem; flex-wrap: wrap; margin-bottom: 1.25rem; }
.section-head .section-title { margin-bottom: 0; }
.muted { color: var(--muted); }
.center { text-align: center; }
.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}
.link-arrow { font-weight: 600; text-decoration: none; }
.link-arrow:hover { text-decoration: underline; }
:focus-visible { outline: 3px solid var(--orange); outline-offset: 2px; }

/* ===== Navbar ===== */
#site-header { position: sticky; top: 0; z-index: 50; }
.navbar {
  display: flex; align-items: center; justify-content: space-between;
  padding: .75rem max(1.25rem, calc((100% - 1200px) / 2));
  background: var(--grad-main);
  box-shadow: 0 4px 18px rgba(108, 92, 231, 0.35);
  color: #fff;
}
.brand { display: flex; align-items: center; gap: .6rem; color: #fff; text-decoration: none; font-size: 1.35rem; }
.brand-logo {
  display: grid; place-items: center; width: 38px; height: 38px; border-radius: 12px;
  background: #fff; color: var(--pink); font-weight: 800; box-shadow: 0 3px 10px rgba(0,0,0,.15);
}
.nav-links { list-style: none; display: flex; gap: .35rem; margin: 0; padding: 0; }
.nav-links a {
  display: flex; align-items: center; gap: .4rem;
  padding: .55rem .95rem; border-radius: 999px;
  color: #fff; text-decoration: none; font-weight: 600;
  transition: background .2s, color .2s, transform .2s;
}
.nav-links a:hover { background: rgba(255,255,255,.2); transform: translateY(-1px); }
.nav-links a.active { background: #fff; color: var(--purple); }
.badge {
  display: inline-grid; place-items: center; min-width: 22px; height: 22px; padding: 0 6px;
  border-radius: 999px; background: var(--yellow); color: var(--ink); font-size: .75rem; font-weight: 800;
}
.nav-toggle {
  display: none; background: rgba(255,255,255,.2); border: 0; border-radius: 10px;
  width: 44px; height: 44px; padding: 10px; cursor: pointer; flex-direction: column; justify-content: space-between;
}
.nav-toggle span { display: block; height: 3px; background: #fff; border-radius: 3px; transition: transform .25s, opacity .25s; }
.nav-toggle.open span:nth-child(1) { transform: translateY(9.5px) rotate(45deg); }
.nav-toggle.open span:nth-child(2) { opacity: 0; }
.nav-toggle.open span:nth-child(3) { transform: translateY(-9.5px) rotate(-45deg); }

/* ===== Buttons ===== */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: .4rem;
  padding: .7rem 1.3rem; border-radius: 999px; border: 2px solid transparent;
  font: inherit; font-weight: 700; text-decoration: none; cursor: pointer;
  transition: transform .15s, box-shadow .2s, background .2s;
}
.btn:hover:not(.is-static) { transform: translateY(-2px); }
.btn:active:not(.is-static) { transform: translateY(0); }
.btn-sm { padding: .45rem .95rem; font-size: .88rem; }
.btn-block { width: 100%; }
.btn-primary { background: linear-gradient(135deg, var(--purple), var(--pink)); color: #fff; box-shadow: 0 6px 16px rgba(232, 67, 147, .35); }
.btn-success { background: linear-gradient(135deg, #00b894, #00cec9); color: #fff; }
.btn-danger { background: linear-gradient(135deg, #e74c3c, #fd9644); color: #fff; }
.btn-ghost { background: #fff; color: var(--purple); border-color: var(--border); }
.btn-ghost:hover { border-color: var(--purple); }
.btn-light { background: #fff; color: var(--pink); }
.btn-outline-light { border-color: #fff; color: #fff; background: transparent; }
.btn-outline-light:hover { background: rgba(255,255,255,.15); }
.btn-disabled { background: #e9e7f3; color: #9a98ad; }
.is-static { cursor: default; }

/* ===== Hero ===== */
.hero { background: var(--grad-main); color: #fff; position: relative; overflow: hidden; padding: 4rem 0 6rem; }
.hero::after {
  content: ""; position: absolute; left: 0; right: 0; bottom: -1px; height: 70px;
  background: var(--bg); clip-path: ellipse(75% 100% at 50% 100%);
}
.hero-inner { display: grid; grid-template-columns: 1.3fr 1fr; gap: 2rem; align-items: center; position: relative; z-index: 1; }
.eyebrow {
  display: inline-block; background: rgba(255,255,255,.2); padding: .3rem .9rem; border-radius: 999px;
  font-weight: 700; font-size: .85rem; letter-spacing: .03em; margin: 0 0 1rem;
}
.hero h1 { font-size: clamp(2.1rem, 5vw, 3.4rem); }
.gradient-text { background: linear-gradient(90deg, #fdcb6e, #fff); -webkit-background-clip: text; background-clip: text; color: transparent; }
.lead { font-size: 1.15rem; opacity: .95; max-width: 34rem; }
.hero-search {
  display: flex; gap: .5rem; background: #fff; padding: .4rem; border-radius: 999px;
  max-width: 34rem; margin: 1.5rem 0 1rem; box-shadow: var(--shadow-lg);
}
.hero-search input { flex: 1; border: 0; outline: none; padding: .6rem 1rem; font: inherit; border-radius: 999px; min-width: 0; }
.hero-actions { display: flex; gap: .75rem; flex-wrap: wrap; }
.hero-art { position: relative; height: 320px; }
.bubble {
  position: absolute; display: grid; place-items: center; border-radius: 50%;
  background: rgba(255,255,255,.18); backdrop-filter: blur(4px); box-shadow: 0 10px 30px rgba(0,0,0,.12);
  animation: float 6s ease-in-out infinite;
}
.b1 { width: 140px; height: 140px; font-size: 4rem; top: 10%; left: 25%; }
.b2 { width: 90px; height: 90px; font-size: 2.6rem; top: 0; right: 8%; animation-delay: -1s; background: rgba(253,203,110,.4); }
.b3 { width: 100px; height: 100px; font-size: 2.8rem; bottom: 5%; left: 5%; animation-delay: -2s; background: rgba(0,184,148,.35); }
.b4 { width: 120px; height: 120px; font-size: 3.2rem; bottom: 0; right: 15%; animation-delay: -3s; background: rgba(9,132,227,.35); }
.b5 { width: 70px; height: 70px; font-size: 2rem; top: 45%; right: 0; animation-delay: -4s; }
@keyframes float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-14px); } }
@media (prefers-reduced-motion: reduce) { .bubble { animation: none; } html { scroll-behavior: auto; } }

/* ===== Stats ===== */
.stats-row { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1rem; margin-top: -3rem; position: relative; z-index: 2; }
.stats-row.compact { margin-top: 0; }
.stat-card {
  border-radius: var(--radius); padding: 1.2rem 1.4rem; color: #fff; box-shadow: var(--shadow);
  display: flex; flex-direction: column; font-weight: 600;
}
.stat-num { font-size: 2.2rem; font-weight: 800; line-height: 1.1; }
.c1 { background: linear-gradient(135deg, #6c5ce7, #a29bfe); }
.c2 { background: linear-gradient(135deg, #e84393, #fd79a8); }
.c3 { background: linear-gradient(135deg, #00b894, #55efc4); }
.c4 { background: linear-gradient(135deg, #fd9644, #fdcb6e); }

/* ===== Department tiles ===== */
.dept-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(170px, 1fr)); gap: 1rem; }
.dept-tile {
  display: flex; flex-direction: column; gap: .2rem; padding: 1.1rem 1.2rem; border-radius: var(--radius);
  background: var(--card); text-decoration: none; color: var(--ink);
  border-left: 6px solid var(--accent); box-shadow: var(--shadow); transition: transform .2s, box-shadow .2s;
}
.dept-tile span { color: var(--accent); font-weight: 600; font-size: .9rem; }
.dept-tile:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }

/* ===== Steps ===== */
.steps { list-style: none; padding: 0; margin: 0; display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; }
.step { background: var(--card); padding: 1.5rem; border-radius: var(--radius); box-shadow: var(--shadow); border-top: 6px solid; }
.step p { margin: 0; color: var(--muted); }
.step-num { display: inline-grid; place-items: center; width: 40px; height: 40px; border-radius: 50%; color: #fff; font-weight: 800; margin-bottom: .75rem; }
.s1 { border-color: var(--purple); } .s1 .step-num { background: var(--purple); }
.s2 { border-color: var(--pink); } .s2 .step-num { background: var(--pink); }
.s3 { border-color: var(--teal); } .s3 .step-num { background: var(--teal); }

/* ===== Page banners ===== */
.page-banner { color: #fff; padding: 2.75rem 0 2.5rem; }
.page-banner h1 { font-size: clamp(1.8rem, 4vw, 2.6rem); }
.page-banner p { margin: 0; opacity: .95; font-size: 1.05rem; }
.banner-catalog { background: linear-gradient(120deg, #0984e3, #6c5ce7 60%, #e84393); }
.banner-register { background: linear-gradient(120deg, #00b894, #0984e3 60%, #6c5ce7); }
.banner-profile { background: linear-gradient(120deg, #fd9644, #e84393 60%, #6c5ce7); }

/* ===== Forms / fields ===== */
.field { display: flex; flex-direction: column; gap: .3rem; }
.field label { font-weight: 600; font-size: .9rem; }
input[type="text"], input[type="email"], input[type="search"], select, textarea {
  font: inherit; color: inherit; padding: .65rem .9rem; border-radius: 12px;
  border: 2px solid var(--border); background: #fff; width: 100%;
  transition: border-color .2s, box-shadow .2s;
}
input:focus, select:focus, textarea:focus { outline: none; border-color: var(--purple); box-shadow: 0 0 0 4px rgba(108, 92, 231, .15); }
.invalid { border-color: var(--red) !important; background: #fff6f5 !important; }
.error-msg { color: var(--red); font-weight: 600; min-height: 1.1em; font-size: .82rem; }
textarea { resize: vertical; }

/* ===== Catalog filters ===== */
.filter-panel { background: var(--card); border-radius: var(--radius); padding: 1.25rem; box-shadow: var(--shadow); margin-bottom: 1.25rem; }
.search-box { position: relative; margin-bottom: 1rem; }
.search-box input { padding-left: 2.6rem; font-size: 1.05rem; }
.search-icon { position: absolute; left: .9rem; top: 50%; transform: translateY(-50%); }
.filters { display: grid; grid-template-columns: repeat(5, 1fr) auto; gap: .9rem; align-items: end; }
.result-count { font-weight: 600; color: var(--muted); margin: 0 0 1rem; }

/* ===== Course cards ===== */
.course-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 1.25rem; }
.course-card {
  background: var(--card); border-radius: var(--radius); padding: 1.25rem; box-shadow: var(--shadow);
  display: flex; flex-direction: column; gap: .6rem; position: relative; overflow: hidden;
  border-top: 6px solid var(--accent); transition: transform .2s, box-shadow .2s;
}
.course-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.course-card-top { display: flex; justify-content: space-between; align-items: center; gap: .5rem; flex-wrap: wrap; }
.course-code { font-weight: 800; color: var(--accent); letter-spacing: .03em; }
.chip {
  font-size: .75rem; font-weight: 700; padding: .2rem .65rem; border-radius: 999px;
  color: var(--accent); background: color-mix(in srgb, var(--accent) 14%, white);
}
.course-title { font-size: 1.15rem; margin: 0; }
.course-desc { margin: 0; color: var(--muted); font-size: .92rem; flex: 1; }
.course-meta { list-style: none; padding: 0; margin: 0; font-size: .88rem; display: grid; gap: .2rem; }
.seats small { color: var(--muted); font-weight: 600; }
.seats .seats-low { color: var(--red); }
.seats-bar { height: 8px; background: #efedf8; border-radius: 99px; overflow: hidden; margin-bottom: .3rem; }
.seats-bar span { display: block; height: 100%; background: linear-gradient(90deg, var(--teal), var(--yellow), var(--red)); background-size: 300px 100%; border-radius: 99px; }
.course-card-actions { display: flex; justify-content: flex-end; }

.empty-state { text-align: center; padding: 2.5rem 1rem; }
.empty-emoji { font-size: 3rem; }

/* ===== Cards & register layout ===== */
.card { background: var(--card); border-radius: var(--radius); padding: 1.5rem; box-shadow: var(--shadow); }
.register-layout { display: grid; grid-template-columns: 1fr 340px; gap: 1.5rem; align-items: start; }
fieldset { border: 0; padding: 0; margin: 0 0 1.75rem; min-width: 0; }
legend { font-size: 1.2rem; font-weight: 800; margin-bottom: 1rem; display: flex; align-items: center; gap: .6rem; padding: 0; }
.legend-num { display: inline-grid; place-items: center; width: 32px; height: 32px; border-radius: 50%; color: #fff; font-size: .95rem; background: var(--grad-main); }
.form-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: .5rem 1rem; }
.picker-tools { display: grid; grid-template-columns: 1fr 220px; gap: .75rem; margin-bottom: .75rem; }
.course-options { display: grid; gap: .55rem; max-height: 420px; overflow-y: auto; padding: .25rem; }
.course-option {
  display: flex; align-items: flex-start; gap: .75rem; padding: .75rem .9rem; border-radius: 12px;
  border: 2px solid var(--border); border-left: 6px solid var(--accent); cursor: pointer; transition: background .2s, border-color .2s;
}
.course-option:hover { background: color-mix(in srgb, var(--accent) 6%, white); }
.course-option:has(input:checked) { background: color-mix(in srgb, var(--accent) 12%, white); border-color: var(--accent); }
.course-option input { margin-top: .3rem; width: 18px; height: 18px; accent-color: var(--accent); flex-shrink: 0; }
.course-option.is-disabled { opacity: .55; cursor: not-allowed; }
.option-body { display: flex; flex-direction: column; }
.option-meta { font-size: .85rem; color: var(--muted); }
.checkbox-field label { display: flex; gap: .6rem; align-items: flex-start; font-weight: 500; }
.checkbox-field input { width: 18px; height: 18px; margin-top: .2rem; accent-color: var(--purple); flex-shrink: 0; }
.form-actions { display: flex; justify-content: flex-end; gap: .75rem; flex-wrap: wrap; }

.summary-card { position: sticky; top: 90px; border-top: 6px solid var(--teal); }
.summary-card h2 { font-size: 1.2rem; }
.summary-list { list-style: none; padding: 0; margin: 0 0 1rem; display: grid; gap: .5rem; }
.summary-list li {
  display: flex; justify-content: space-between; align-items: center; gap: .5rem;
  padding: .55rem .75rem; border-radius: 10px; background: color-mix(in srgb, var(--accent, #6c5ce7) 12%, white);
  border-left: 4px solid var(--accent, #6c5ce7); font-size: .9rem;
}
.summary-list li.empty { background: #f4f3fa; border-left-color: #ccc; }
.remove-btn { border: 0; background: rgba(0,0,0,.08); width: 26px; height: 26px; border-radius: 50%; cursor: pointer; font-size: 1.1rem; line-height: 1; flex-shrink: 0; }
.remove-btn:hover { background: var(--red); color: #fff; }
.credit-box { margin-bottom: 1rem; }
.credit-head { display: flex; justify-content: space-between; font-weight: 600; margin-bottom: .4rem; gap: .5rem; }
.meter { height: 12px; background: #efedf8; border-radius: 99px; overflow: hidden; margin-bottom: .3rem; }
.meter span { display: block; height: 100%; width: 0; background: linear-gradient(90deg, var(--teal), var(--blue), var(--purple)); border-radius: 99px; transition: width .4s; }
.meter span.over { background: linear-gradient(90deg, var(--orange), var(--red)); }

/* ===== Profile ===== */
.profile-layout { display: grid; grid-template-columns: 300px 1fr; gap: 1.5rem; align-items: start; }
.profile-card { text-align: center; border-top: 6px solid var(--pink); }
.avatar {
  width: 96px; height: 96px; border-radius: 50%; margin: 0 auto 1rem; display: grid; place-items: center;
  background: var(--grad-main); color: #fff; font-size: 2.2rem; font-weight: 800; box-shadow: var(--shadow-lg);
}
.profile-details { text-align: left; margin: 1.25rem 0; display: grid; grid-template-columns: auto 1fr; gap: .5rem .75rem; font-size: .92rem; }
.profile-details dt { font-weight: 700; color: var(--purple); }
.profile-details dd { margin: 0; word-break: break-word; }
.profile-main { display: grid; gap: 1.25rem; min-width: 0; }
.table-tools { display: flex; gap: .75rem; margin-bottom: 1rem; flex-wrap: wrap; }
.table-tools input { flex: 1 1 220px; }
.table-tools select { flex: 0 1 200px; }

/* ===== Data table ===== */
.table-wrap { overflow-x: auto; border-radius: 12px; }
.data-table { width: 100%; border-collapse: collapse; font-size: .92rem; }
.data-table th, .data-table td { padding: .75rem .8rem; text-align: left; white-space: nowrap; }
.data-table thead th { background: linear-gradient(135deg, var(--purple), var(--pink)); color: #fff; font-weight: 700; position: relative; }
.data-table thead th[data-sort] { cursor: pointer; user-select: none; }
.data-table thead th[data-sort]::after { content: " ⇅"; opacity: .6; font-size: .8em; }
.data-table thead th[aria-sort="ascending"]::after { content: " ▲"; opacity: 1; }
.data-table thead th[aria-sort="descending"]::after { content: " ▼"; opacity: 1; }
.data-table tbody tr { border-bottom: 1px solid var(--border); transition: background .15s; }
.data-table tbody tr:nth-child(even) { background: #faf9ff; }
.data-table tbody tr:hover { background: color-mix(in srgb, var(--accent, #6c5ce7) 8%, white); }
.data-table tbody td:first-child { border-left: 5px solid var(--accent, transparent); }
.data-table tfoot td { font-weight: 800; background: #f1effd; }
.code-pill { display: inline-block; padding: .2rem .6rem; border-radius: 999px; font-weight: 800; color: #fff; background: var(--accent); font-size: .8rem; }

/* ===== Modal ===== */
.modal-overlay {
  position: fixed; inset: 0; z-index: 100; background: rgba(35, 25, 80, .55); backdrop-filter: blur(3px);
  display: grid; place-items: center; padding: 1rem; opacity: 0; transition: opacity .2s;
}
.modal-overlay.show { opacity: 1; }
.modal {
  background: #fff; border-radius: 20px; width: min(560px, 100%); max-height: 90vh; overflow-y: auto;
  box-shadow: 0 30px 60px rgba(0,0,0,.3); transform: translateY(20px) scale(.97); transition: transform .25s;
}
.modal-overlay.show .modal { transform: none; }
.modal-header { display: flex; justify-content: space-between; align-items: center; padding: 1.1rem 1.4rem; background: var(--grad-main); color: #fff; border-radius: 20px 20px 0 0; }
.modal-header h2 { margin: 0; font-size: 1.25rem; }
.modal-close { background: rgba(255,255,255,.25); border: 0; color: #fff; width: 34px; height: 34px; border-radius: 50%; font-size: 1.4rem; cursor: pointer; line-height: 1; }
.modal-close:hover { background: rgba(255,255,255,.4); }
.modal-body { padding: 1.25rem 1.4rem; }
.modal-footer { display: flex; justify-content: flex-end; gap: .6rem; padding: 0 1.4rem 1.3rem; flex-wrap: wrap; }
.confirm-details { display: grid; grid-template-columns: auto 1fr; gap: .3rem .75rem; margin: 0 0 1rem; font-size: .92rem; }
.confirm-details dt { font-weight: 700; color: var(--purple); }
.confirm-details dd { margin: 0; word-break: break-word; }
.mini-table { width: 100%; border-collapse: collapse; font-size: .9rem; }
.mini-table th, .mini-table td { padding: .5rem .6rem; text-align: left; border-bottom: 1px solid var(--border); }
.mini-table th { background: #f1effd; color: var(--purple); }
.mini-table tfoot td { font-weight: 800; border-bottom: 0; }

/* ===== Toast ===== */
.toast-container { position: fixed; bottom: 1.25rem; right: 1.25rem; z-index: 200; display: grid; gap: .5rem; }
.toast {
  padding: .8rem 1.2rem; border-radius: 12px; color: #fff; font-weight: 600; box-shadow: var(--shadow-lg);
  animation: toast-in .3s ease; transition: opacity .4s, transform .4s;
}
.toast.hide { opacity: 0; transform: translateY(10px); }
.toast-success { background: linear-gradient(135deg, #00b894, #00cec9); }
.toast-error { background: linear-gradient(135deg, #e74c3c, #fd9644); }
.toast-info { background: linear-gradient(135deg, #0984e3, #6c5ce7); }
@keyframes toast-in { from { opacity: 0; transform: translateY(10px); } }

/* ===== Footer ===== */
.site-footer { margin-top: 2rem; padding: 1.5rem 1rem; text-align: center; color: #fff; background: linear-gradient(90deg, #2d3047, #6c5ce7); font-size: .9rem; }
.site-footer p { margin: 0; }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .filters { grid-template-columns: repeat(3, 1fr); }
  .reset-btn { grid-column: span 1; }
  .register-layout { grid-template-columns: 1fr; }
  .summary-card { position: static; order: -1; }
  .profile-layout { grid-template-columns: 1fr; }
  .profile-card { display: grid; grid-template-columns: auto 1fr; text-align: left; gap: 0 1.5rem; align-items: center; }
  .profile-card .avatar { grid-row: span 2; margin: 0; }
  .profile-card .profile-details, .profile-card .btn { grid-column: 1 / -1; }
}

@media (max-width: 860px) {
  .nav-toggle { display: flex; }
  .navbar { flex-wrap: wrap; }
  .nav-links {
    display: none; flex-direction: column; width: 100%; padding-top: .75rem; gap: .25rem;
  }
  .nav-links.open { display: flex; }
  .nav-links a { border-radius: 12px; }
  .hero-inner { grid-template-columns: 1fr; }
  .hero-art { display: none; }
  .stats-row { grid-template-columns: repeat(2, 1fr); }
  .steps { grid-template-columns: 1fr; }
}

@media (max-width: 640px) {
  .container { width: min(1200px, 100% - 1.5rem); }
  .hero { padding: 2.5rem 0 5rem; }
  .hero-search { flex-direction: column; border-radius: 18px; }
  .hero-search .btn { width: 100%; }
  .filters { grid-template-columns: 1fr 1fr; }
  .reset-btn { grid-column: 1 / -1; }
  .form-grid { grid-template-columns: 1fr; }
  .picker-tools { grid-template-columns: 1fr; }
  .form-actions .btn { flex: 1; }
  .stat-num { font-size: 1.7rem; }
  .card { padding: 1.1rem; }
  .profile-card { display: block; text-align: center; }
  .profile-card .avatar { margin: 0 auto 1rem; }

  /* Data table becomes stacked cards */
  .data-table thead { display: none; }
  .data-table, .data-table tbody, .data-table tr, .data-table td, .data-table tfoot { display: block; width: 100%; }
  .data-table tbody tr { border: 2px solid var(--border); border-left: 6px solid var(--accent, var(--purple)); border-radius: 12px; margin-bottom: .75rem; padding: .4rem 0; background: #fff !important; }
  .data-table td { display: flex; justify-content: space-between; gap: 1rem; padding: .4rem .9rem; white-space: normal; text-align: right; }
  .data-table td::before { content: attr(data-label); font-weight: 700; color: var(--purple); text-align: left; }
  .data-table tbody td:first-child { border-left: 0; }
  .data-table td[colspan]::before { content: none; }
  .data-table tfoot tr { display: flex; justify-content: space-between; border-radius: 12px; overflow: hidden; }
  .data-table tfoot td { width: auto; }
}

@media (max-width: 420px) {
  .filters { grid-template-columns: 1fr; }
  .stats-row { gap: .6rem; }
  .stat-card { padding: .9rem 1rem; }
}

