  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error' || m.type()==='warning') errors.push(m.type()+': ' + m.text()); });
  const B = 'http://localhost:8765/';
  await page.goto(B + 'index.html');
  console.log('home stats', await page.textContent('#stat-courses'), await page.$$eval('#featured-grid .course-card', e=>e.length));
  await page.screenshot({ path: '/tmp/pwtest/home.png', fullPage: true });
  // nav
  for (const label of ['Course Catalog','Registration','My Profile','Home']) {
    await page.click(`.nav-links a:has-text("${label}")`);
    console.log('nav ->', page.url(), await page.textContent('h1'));
  }
  // search from home
  await page.fill('#hero-q', 'genetics'); await page.press('#hero-q', 'Enter');
  await page.waitForURL(/catalog/);
  console.log('search cards', await page.$$eval('.course-card', e=>e.length), await page.textContent('#result-count'));
  await page.click('#reset-filters');
  await page.selectOption('#filter-dept', 'Mathematics');
  console.log('math cards', await page.$$eval('.course-card', e=>e.length));
  await page.selectOption('#filter-availability', 'open'); await page.selectOption('#filter-dept', '');
  console.log('open cards', await page.$$eval('.course-card', e=>e.length));
  await page.screenshot({ path: '/tmp/pwtest/catalog.png', fullPage: true });
  await page.click('.course-card >> nth=0 >> text=Register');
  console.log('register url', page.url(), await page.$$eval('#summary-list li', e=>e.map(x=>x.textContent.trim())));
  await page.check('input[value="ART140"]');
  // submit without agree
  await page.click('button[type=submit]');
  console.log('agree err', await page.textContent('#agree-error'));
  await page.check('#agree');
  await page.click('button[type=submit]');
  await page.waitForSelector('.modal');
  await page.screenshot({ path: '/tmp/pwtest/modal.png' });
  console.log('modal', await page.textContent('#modal-title'));
  await page.click('[data-action=confirm]');
  await page.waitForSelector('#modal-title:has-text("complete")');
  await page.click('[data-action=confirm]');
  await page.waitForURL(/profile/);
  console.log('rows', await page.$$eval('#reg-tbody tr', e=>e.length), await page.textContent('#reg-total'), 'badge', await page.textContent('.badge'));
  await page.click('th[data-sort=credits]');
  await page.screenshot({ path: '/tmp/pwtest/profile.png', fullPage: true });
  await page.click('[data-drop] >> nth=0'); await page.click('[data-action=confirm]');
  console.log('rows after drop', await page.$$eval('#reg-tbody tr', e=>e.length));
  // mobile
  await page.setViewportSize({ width: 375, height: 800 });
  for (const p of ['index','catalog','register','profile']) {
    await page.goto(B + p + '.html');
    const ow = await page.evaluate(() => document.documentElement.scrollWidth);
    console.log('mobile', p, 'scrollWidth', ow);
    await page.screenshot({ path: `/tmp/pwtest/m-${p}.png`, fullPage: true });
  }
  await page.click('.nav-toggle');
  await page.click('.nav-links a:has-text("Home")');
  console.log('mobile nav ok', page.url());
  console.log('ERRORS:', errors.length ? errors : 'none');
  await browser.close();
})();
EOF
