const { JSDOM, VirtualConsole } = require('jsdom');
const B = 'http://localhost:8765/';
const errors = [];
const store = {};
async function open(path) {
  const vc = new VirtualConsole();
  vc.on('jsdomError', e => errors.push(path + ' jsdomError: ' + (e.message||e)));
  vc.on('error', e => errors.push(path + ' console.error: ' + e));
  vc.on('warn', e => errors.push(path + ' console.warn: ' + e));
  const dom = await JSDOM.fromURL(B + path, { resources: 'usable', runScripts: 'dangerously', virtualConsole: vc, pretendToBeVisual: true,
    beforeParse(w) {
      Object.defineProperty(w, 'localStorage', { value: { getItem: k => store[k] ?? null, setItem: (k, v) => { store[k] = String(v); }, removeItem: k => delete store[k] } });
      w.Element.prototype.scrollIntoView = function () {};
    } });
  await new Promise(r => dom.window.addEventListener('load', r));
  await new Promise(r => setTimeout(r, 50));
  return dom.window;
}
const click = (w, el) => el.dispatchEvent(new w.MouseEvent('click', { bubbles: true }));
(async () => {
  let w = await open('index.html');
  let d = w.document;
  console.log('home: nav links', [...d.querySelectorAll('.nav-links a')].map(a => a.getAttribute('href')+(a.classList.contains('active')?'*':'')).join(' '));
  console.log('home stats', d.getElementById('stat-courses').textContent, d.getElementById('stat-depts').textContent, 'featured', d.querySelectorAll('#featured-grid .course-card').length, 'depts', d.querySelectorAll('.dept-tile').length);

  w = await open('catalog.html?q=genetics'); d = w.document;
  console.log('catalog q=genetics', d.querySelectorAll('.course-card').length, d.getElementById('result-count').textContent);
  click(w, d.getElementById('reset-filters'));
  console.log('reset', d.querySelectorAll('.course-card').length);
  const dept = d.getElementById('filter-dept'); dept.value = 'Mathematics'; dept.dispatchEvent(new w.Event('change'));
  console.log('math', d.querySelectorAll('.course-card').length);
  dept.value = ''; dept.dispatchEvent(new w.Event('change'));
  const av = d.getElementById('filter-availability'); av.value = 'open'; av.dispatchEvent(new w.Event('change'));
  console.log('open', d.querySelectorAll('.course-card').length, 'full courses shown as', d.querySelectorAll('.btn-disabled').length);
  const s = d.getElementById('search'); s.value = 'zzzz'; s.dispatchEvent(new w.Event('input'));
  console.log('empty state hidden?', d.getElementById('empty-state').hidden);

  w = await open('register.html?course=CS340'); d = w.document;
  console.log('preselect', [...d.querySelectorAll('#summary-list li')].map(l => l.textContent.trim().replace(/\s+/g,' ')));
  console.log('prefill name', d.getElementById('name').value, 'disabled options', d.querySelectorAll('.course-option.is-disabled').length);
  const cb = d.querySelector('input[value="ART140"]'); cb.checked = true; cb.dispatchEvent(new w.Event('change', { bubbles: true }));
  console.log('credits', d.getElementById('summary-credits').textContent);
  const form = d.getElementById('register-form');
  form.requestSubmit();
  console.log('agree error:', d.getElementById('agree-error').textContent, 'modal?', !!d.querySelector('.modal'));
  d.getElementById('agree').checked = true;
  form.requestSubmit();
  console.log('modal title', d.getElementById('modal-title').textContent, 'rows', d.querySelectorAll('.mini-table tbody tr').length);
  click(w, d.querySelector('[data-action=confirm]'));
  console.log('success modal', d.getElementById('modal-title').textContent, 'badge', d.querySelector('.badge')?.textContent);
  click(w, d.querySelector('[data-action=cancel]'));
  console.log('modal closed', !d.querySelector('.modal'), 'CS340 now disabled', d.querySelector('input[value="CS340"]').disabled);
  // credit limit
  ['CS101','MATH110','PHYS101','BIO120','CS410'].forEach(id => { const c = d.querySelector(`input[value="${id}"]`); c.checked = true; c.dispatchEvent(new w.Event('change', { bubbles: true })); });
  d.getElementById('agree').checked = true; form.requestSubmit();
  console.log('limit error:', d.getElementById('course-error').textContent);

  w = await open('profile.html'); d = w.document;
  console.log('profile rows', d.querySelectorAll('#reg-tbody tr').length, d.getElementById('reg-total').textContent, 'stats', d.getElementById('s-credits').textContent, d.getElementById('avatar').textContent);
  click(w, d.querySelector('th[data-sort=credits]'));
  console.log('sorted', [...d.querySelectorAll('#reg-tbody tr td:first-child')].map(t=>t.textContent).join(','), d.querySelector('th[data-sort=credits]').getAttribute('aria-sort'));
  click(w, d.querySelector('[data-drop]'));
  click(w, d.querySelector('[data-action=confirm]'));
  console.log('after drop rows', d.querySelectorAll('#reg-tbody tr').length);
  click(w, d.getElementById('drop-all')); click(w, d.querySelector('[data-action=confirm]'));
  console.log('empty shown', !d.getElementById('reg-empty').hidden, 'table hidden', d.getElementById('reg-table-wrap').hidden);
  await new Promise(r => setTimeout(r, 100));
  console.log('ERRORS:', errors.length ? errors : 'none');
  process.exit(0);
})();
